"""Import pinned minecraft-data wire metadata; never infer C++ memory offsets."""
import argparse,hashlib,json,urllib.request
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
COMMIT='9c97fe50a82feb2c0f2be1cff35ce19c891bfb35'
BASE=f'https://raw.githubusercontent.com/PrismarineJS/minecraft-data/{COMMIT}/data/bedrock/1.26.60'

def generate(protocol_bytes,version_bytes):
 types=json.loads(protocol_bytes)['types'];version=json.loads(version_bytes)
 ids={name:int(number) for number,name in types['mcpe_packet'][1][0]['type'][1]['mappings'].items()}
 flags={name:int(number) for number,name in types['InputData'][1]['mappings'].items()}
 names=['move_player','player_auth_input','command_request','command_output']
 expected={'move_player':19,'player_auth_input':144,'command_request':77,'command_output':79}
 if {name:ids[name] for name in names}!=expected:raise ValueError('packet identity changed; review SDK consumers')
 if version['minecraftVersion']!='1.26.60':raise ValueError('wrong source version')
 data={'schema':1,'scope':'wire protocol metadata, not C++ object offsets','source':{'repository':'PrismarineJS/minecraft-data','commit':COMMIT,'url':BASE+'/protocol.json','sha256':hashlib.sha256(protocol_bytes).hexdigest()},'version':version,'packet_ids':ids,'packets':{name:{'id':ids[name],'wire_definition':types['packet_'+name]} for name in names},'input_data':flags}
 target=ROOT/'data/protocols/bedrock-1.26.60.json';target.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 camel=lambda name:''.join(part.title() for part in name.split('_'))
 lines=['#pragma once','#include <array>','#include <cstdint>','#include <string_view>','', '// Generated by tools/import_bedrock_protocol.py from minecraft-data; see third_party/notices/minecraft-data.txt.',f'// Source commit {COMMIT}; these are wire enums, NOT native offsets.','namespace bedrock::protocol::v1_26_60 {',f'inline constexpr unsigned protocolVersion={version["version"]};']
 for name in names:lines.append(f'inline constexpr std::uint16_t {camel(name)}Id={ids[name]};')
 lines+=['enum class PacketType : std::uint16_t {']+[f'    {camel(name)}={value},' for name,value in ids.items()]+['};']
 lines+=['constexpr std::string_view packetName(std::uint16_t id) noexcept {','    switch(id){']+[f'    case {value}:return \"{name}\";' for name,value in ids.items()]+['    default:return \"unknown\";','    }','}']
 lines+=['enum class InputData : unsigned {']+[f'    {camel(name)}={index},' for name,index in flags.items()]+['};']
 # Explicit movement policy. Conditional transaction/stack/action payload flags
 # and acknowledgements are intentionally not in this named list.
 movement=[name for name,index in flags.items() if index<34 or index in {40,41,42,43,45,46,47,51,52,54,55,56,57,59,60,61,62,63,64}]
 lines+=['inline constexpr std::array movementControls{']+['    InputData::'+camel(name)+',' for name in movement]+['};','constexpr void clearMovement(std::array<std::uint64_t,2>& flags) noexcept {','    for(auto flag:movementControls){const auto bit=static_cast<unsigned>(flag); flags[bit/64]&=~(std::uint64_t{1}<<(bit%64));}','}','constexpr bool has(const std::array<std::uint64_t,2>& flags,InputData flag) noexcept {','    const auto bit=static_cast<unsigned>(flag);return (flags[bit/64]&(std::uint64_t{1}<<(bit%64)))!=0;','}','} // namespace bedrock::protocol::v1_26_60','']
 (ROOT/'include/bedrock/detail/protocol_1_26_60.hpp').write_text('\n'.join(lines),encoding='utf-8')

if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--source',type=Path);p.add_argument('--version-source',type=Path);args=p.parse_args()
 if bool(args.source)!=bool(args.version_source):p.error('both local source files are required')
 if args.source:protocol=args.source.read_bytes();version=args.version_source.read_bytes()
 else:
  protocol=urllib.request.urlopen(BASE+'/protocol.json',timeout=30).read();version=urllib.request.urlopen(BASE+'/version.json',timeout=30).read()
 generate(protocol,version)
